// Script para migrar contenido de MongoDB a archivos JSON
// y dejar solo metadatos en MongoDB

const { MongoClient } = require('mongodb');
const fs = require('fs');
const path = require('path');

const MONGO_URI = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/tourtovalencia';

async function migrateMongoDBContent() {
  const client = new MongoClient(MONGO_URI);

  try {
    await client.connect();
    const db = client.db('tourtovalencia');

    console.log('Migrando contenido de tours...');
    const tours = await db.collection('tours').find({}).toArray();

    for (const tour of tours) {
      // Extraer contenido traducible
      const translations = {
        es: {},
        en: {}
      };

      const fields = ['tourName', 'description', 'duration', 'includes', 'meetingPoint'];
      for (const field of fields) {
        if (tour[field]) {
          if (tour[field].es) translations.es[field] = tour[field].es;
          if (tour[field].en) translations.en[field] = tour[field].en;
        }
      }

      // Escribir a archivo JSON
      // (llamar a saveTourTranslationsToJson)

      // Actualizar documento en MongoDB para eliminar campos
      await db.collection('tours').updateOne(
        { _id: tour._id },
        {
          $unset: {
            tourName: "",
            description: "",
            duration: "",
            includes: "",
            meetingPoint: ""
          }
        }
      );

      console.log(`Tour ${tour.slug} migrado`);
    }

    console.log('\nMigración completada');

  } finally {
    await client.close();
  }
}

migrateMongoDBContent().catch(console.error);
